#include <linux/uaccess.h>
#include <linux/socket.h>
#include <linux/file.h>
#include <linux/sockios.h>
#include <linux/net.h>

int receive_data(int fd, void __user *ubuf, size_t size, unsigned int flags,
                 struct sockaddr __user *addr, int __user *addr_len) {
    struct socket *sock;
    struct msghdr msg;
    struct iovec iov;
    int ret;

    if (!ubuf || !size)
        return -EINVAL;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    iov.iov_base = ubuf;
    iov.iov_len = size;

    msg.msg_name = addr;
    msg.msg_namelen = 0;
    if (addr_len && get_user(msg.msg_namelen, addr_len) < 0) {
        ret = -EFAULT;
        goto out;
    }

    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = flags;

    ret = sock_recvmsg(sock, &msg, size, flags);
    if (ret < 0)
        goto out;

    if (addr_len && put_user(msg.msg_namelen, addr_len) < 0)
        ret = -EFAULT;

out:
    sockfd_put(sock);
    return ret;
}

#include <sys/socket.h>
#include <linux/uaccess.h>
#include <linux/kernel.h>
#include <linux/file.h>
#include <linux/fs.h>

int recv_from_socket(int fd, void __user *ubuf, size_t size, unsigned int flags,
                     struct sockaddr __user *addr, int __user *addr_len) {
    struct file *file;
    struct socket *sock;
    struct msghdr msg;
    struct iovec iov;
    int ret;

    if (!ubuf || !size)
        return -EINVAL;

    file = fget(fd);
    if (!file)
        return -EBADF;

    sock = sock_from_file(file, NULL);
    if (!sock) {
        fput(file);
        return -EBADF;
    }

    iov.iov_base = ubuf;
    iov.iov_len = size;
    msg.msg_name = addr;
    msg.msg_namelen = addr ? sizeof(struct sockaddr_storage) : 0;
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = flags;

    ret = sock->ops->recvmsg(NULL, sock, &msg, size, flags, NULL);
    if (ret > 0 && addr && msg.msg_namelen) {
        int len;
        if (get_user(len, addr_len))
            ret = -EFAULT;
        else {
            len = min(len, msg.msg_namelen);
            if (copy_to_user(addr, msg.msg_name, len))
                ret = -EFAULT;
            if (put_user(len, addr_len))
                ret = -EFAULT;
        }
    }

    fput(file);
    return ret;
}

