int sock_recv(int fd, void __user *ubuf, size_t size, unsigned int flags,
              struct sockaddr __user *addr, int __user *addr_len) {
    struct socket *sock;
    struct msghdr msg = {};
    struct iovec iov;
    int ret;

    if (!ubuf || !size)
        return -EINVAL;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    iov.iov_base = ubuf;
    iov.iov_len = size;
    msg.msg_name = addr;
    msg.msg_namelen = addr ? sizeof(struct sockaddr) : 0;
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = flags;

    ret = kernel_recvmsg(sock, &msg, NULL, size, size, flags);
    if (ret > 0 && addr) {
        ret = copy_to_user(addr_len, &msg.msg_namelen, sizeof(int));
        if (ret)
            ret = -EFAULT;
    }

    sockfd_put(sock);
    return ret;
}

#include <sys/socket.h>
#include <linux/uaccess.h>
#include <linux/sockios.h>
#include <linux/file.h>
#include <linux/fs.h>
#include <linux/errno.h>
#include <linux/mm.h>

int sock_recvmsg(int fd, void __user *ubuf, size_t size, unsigned int flags,
                 struct sockaddr __user *addr, int __user *addr_len)
{
    struct socket *sock;
    struct msghdr msg;
    struct iovec iov;
    int len, err;

    if (!addr_len)
        return -EINVAL;

    sock = sockfd_lookup(fd, &err);
    if (!sock)
        return err;

    iov.iov_base = ubuf;
    iov.iov_len = size;

    msg.msg_name = addr;
    msg.msg_namelen = sizeof(*addr);
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = NULL;
    msg.msg_controllen = 0;
    msg.msg_flags = flags;

    len = sock->ops->recvmsg(NULL, sock, &msg, size, flags, NULL);
    if (len >= 0) {
        if (addr) {
            int alen;
            if (get_user(alen, addr_len))
                len = -EFAULT;
            else {
                if (copy_to_user(addr, msg.msg_name, alen))
                    len = -EFAULT;
            }
        }
    }

    sockfd_put(sock);
    return len;
}

#include <linux/socket.h>
