int handle_sock_recv(int fd, void __user *ubuf, size_t size, unsigned int flags, struct sockaddr __user *addr, int __user *addr_len) {
    struct socket *sock;
    struct msghdr msg;
    struct iovec iov;
    int ret;

    if (!ubuf || !size)
        return -EINVAL;

    sock = sockfd_lookup(fd, &ret);
    if (!sock)
        return ret;

    iov.iov_base = ubuf;
    iov.iov_len = size;

    memset(&msg, 0, sizeof(msg));
    msg.msg_name = addr;
    msg.msg_namelen = addr ? sizeof(struct sockaddr) : 0;
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_flags = flags;

    ret = sock_recvmsg(sock, &msg, msg.msg_flags);

    if (ret > 0 && addr && msg.msg_namelen) {
        if (copy_to_user(addr_len, &msg.msg_namelen, sizeof(int)))
            ret = -EFAULT;
    }

    sockfd_put(sock);
    return ret;
}
